  const QUEST_ICONS = Object.freeze({target:'<svg viewBox="0 0 64 64"><circle cx="32" cy="32" r="24"/><circle cx="32" cy="32" r="13"/><path d="M32 2v14M32 48v14M2 32h14M48 32h14"/></svg>',bullet:'<svg viewBox="0 0 64 64"><path d="M8 38 39 7l18 18-31 31H8Z"/><path d="m34 13 17 17M12 40l12 12"/></svg>',spray:'<svg viewBox="0 0 64 64"><path d="M18 27h29v29H18Z"/><path d="M24 17h17l6 10H24Z"/><circle cx="13" cy="18" r="4"/><circle cx="5" cy="12" r="2"/></svg>',bolt:'<svg viewBox="0 0 64 64"><path d="m37 3-24 34h17l-3 24 24-35H35Z"/></svg>',brick:'<svg viewBox="0 0 64 64"><path d="M4 17h56v34H4ZM4 34h56M23 17v17m20 0v17"/></svg>',blast:'<svg viewBox="0 0 64 64"><path d="m32 2 6 19L54 9l-9 18 18 5-18 6 9 17-17-11-5 18-6-18L9 55l10-18-18-5 19-6L9 9l17 12Z"/></svg>'});
