  const readQuestState=()=>{if(serverHostedRoom)return serverQuestState;try{return JSON.parse(localStorage.getItem(questStorageKey())||'{}');}catch{return {};}};
  function renderGameQuests(){const state=readQuestState();questPanel.innerHTML=`<header><div><small>LIVE FIELD OPS</small><h2>RAD-TOX Quests</h2><p>Actions count instantly. Claim completed ops for MZK.</p></div><button type="button" data-quest-close aria-label="Close quests">×</button></header><div class="rad-quest-list">${GAME_QUESTS.map(q=>{const item=state[q.id]||{},value=Math.min(q.goal,item.progress||0),done=value>=q.goal;return `<article class="rad-quest-card ${done?'is-complete':''} ${item.claimed?'is-claimed':''}" data-quest-card="${q.id}"><span class="rad-quest-icon">${QUEST_ICONS[q.icon]}</span><div><strong>${q.title}</strong><p>${q.copy}</p><span class="rad-quest-progress"><i style="--quest-progress:${value/q.goal*100}%"></i></span><small>${value}/${q.goal} · +${q.reward} MZK</small></div><button type="button" data-quest-claim="${q.id}" ${done&&!item.claimed?'':'disabled'}>${item.claimed?'Claimed':done?'Claim':'In progress'}</button></article>`}).join('')}</div>`;}
  function showQuestToast(quest,claimed=false){questToast.innerHTML=`<span class="rad-quest-toast__burst">${QUEST_ICONS[claimed?'blast':quest.icon]}</span><span><small>${claimed?'REWARD SECURED':'QUEST COMPLETE'}</small><strong>${quest.title}</strong><b>${claimed?`+${quest.reward} MZK`:'Open Quests to claim'}</b></span>`;questToast.classList.remove('is-visible');void questToast.offsetWidth;questToast.classList.add('is-visible');window.setTimeout(()=>questToast.classList.remove('is-visible'),3200);}
  function trackGameQuest(event,amount=1){if(serverHostedRoom)return;window.MZKWallet?.rewardProgress?.('field',event).catch(()=>{});const state=readQuestState();GAME_QUESTS.filter(q=>q.event===event).forEach(q=>{const item=state[q.id]||{progress:0,claimed:false},wasDone=item.progress>=q.goal;item.progress=Math.min(q.goal,item.progress+amount);state[q.id]=item;if(!wasDone&&item.progress>=q.goal)showQuestToast(q);});localStorage.setItem(questStorageKey(),JSON.stringify(state));renderGameQuests();}
  function toggleGameQuests(force){const open=force??questPanel.hidden;questPanel.hidden=!open;sprayTools.querySelector('[data-rad-quests-toggle]')?.setAttribute('aria-expanded',String(open));if(open){inventoryPack.hidden=true;toggleBuildMenu(false);renderGameQuests();}}
