    setBrickMaterial(id){if(gameEconomy?.pending.size&&id!==this.brickMaterialId)return false;this.buildEditor.cancel();const profile=buildingMaterial(id);this.brickMaterialId=profile.id;this.brickTint=null;this.buildRotation=0;localStorage.setItem('muzikazBrickMaterial',profile.id);for(const object of [this.brickModel,this.brickPreview]){object.traverse(child=>{child.geometry?.dispose();child.material?.dispose();});object.removeFromParent();}this.brickModel=this.createBrickMesh({held:true});this.camera.add(this.brickModel);this.brickPreview=this.createBrickPreview();this.brickGroup.add(this.brickPreview);buildingPopup.querySelectorAll('[data-brick-material]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.brickMaterial===profile.id)));document.querySelectorAll('[data-brick-color]').forEach(button=>button.setAttribute('aria-pressed','false'));buildingPopup.querySelector('[data-brick-material-label]').textContent=profile.name;buildingPopup.querySelector('[data-building-paint-label]').textContent='Natural finish';this.setTool('brick');gameEconomy?.decorate();this.refreshBuildingPreview();this.setState(this.state,`${profile.name} selected — ${profile.solid?'snap, stack and climb':'translucent pass-through water blocks'}.`);}
    refreshBuildingPreview(){
      if(buildingPopup.hidden)return;
      buildingPopup.querySelectorAll('[data-build-transform],[data-building-lock],[data-building-cancel]').forEach(control=>control.disabled=!this.buildEditor.pending);
      try{if(!this.previewViewer)this.previewViewer=new BuildingPreview(THREE,buildingPopup.querySelector('[data-building-3d-preview]'));
      if(this.previewModel){this.previewModel.traverse(mesh=>{mesh.geometry?.dispose();mesh.material?.dispose();});this.previewModel=null;}
      const root=this.buildEditor.pending?.root||(this.previewModel=this.createBrickMesh());this.previewViewer.set(root);
      }catch(error){buildingPopup.querySelector('[data-building-edit-status]').textContent='3D preview unavailable. Placement and transform controls are still usable.';}
    }
    beginBuildingEdit(root,isNew=false){this.buildEditor.begin(root,isNew);buildingPopup.hidden=false;
      buildingPopup.querySelectorAll('[data-build-transform]').forEach(input=>{input.value=input.dataset.buildTransform==='scale'?1:0;buildingPopup.querySelector(`[data-build-value="${input.dataset.buildTransform}"]`).textContent=input.value;});
      buildingPopup.querySelector('[data-building-edit-status]').textContent=isNew?'New piece staged. Drag axis sliders, then lock or cancel.':'Editing placed piece. Lock to save; cancel restores it.';
      this.refreshBuildingPreview();}
    editAimedBuilding(){const hit=this.brickAtRay(new THREE.Vector2(0,0));if(!hit){this.setState(this.state,'Aim at a placed building item first.');return;}this.buildEditor.cancel();this.setBrickMaterial(hit.root.userData.materialId);this.beginBuildingEdit(hit.root);}
