    cancelBuildingEdit(){this.buildEditor.cancel();buildingPopup.querySelector('[data-building-spin]').setAttribute('aria-pressed','false');this.refreshBuildingPreview();}
    updateBuildingEditor(delta){if(buildingPopup.hidden)return;this.buildEditor.update(delta);if(this.previewSpin&&!this.buildEditor.pending&&this.previewModel)this.previewModel.rotation.y+=delta*.8;if(this.previewViewer){const source=this.buildEditor.pending?.root||this.previewModel;if(source)this.previewViewer.render(source);}if(this.buildEditor.spin){const value=this.buildEditor.values.ry;const slider=buildingPopup.querySelector('[data-build-transform="ry"]'),output=buildingPopup.querySelector('[data-build-value="ry"]');if(slider)slider.value=value;if(output)output.textContent=Math.round(value);}}
