    brickAtRay(pointer,origin=null,direction=null){if(origin&&direction)this.raycaster.set(origin,direction);else this.raycaster.setFromCamera(pointer,this.camera);const hit=this.raycaster.intersectObjects(this.bricks,true)[0];if(!hit)return null;let root=hit.object;while(root.parent&&root.parent!==this.brickGroup)root=root.parent;return root.userData.brick?{root,point:hit.point}:null;}
