    swingBat(){if(!this.ownsBat)return false;if(this.batSwing>0){this.batSwingQueue=Math.min(3,this.batSwingQueue+1);return true;}return this.startBatSwing();} startBatSwing(){this.batSwing=TOXIC_BUBBLE_CONFIG.batSwingDuration;this.batHitIds.clear();this.tone(125,.09,'triangle',.08);const origin=this.camera.getWorldPosition(new THREE.Vector3()),direction=this.camera.getWorldDirection(new THREE.Vector3());let hit=false;for(const target of [...this.bubbles]){const point=target.getWorldPosition(new THREE.Vector3()),offset=point.sub(origin),distance=offset.length();if(distance<=TOXIC_BUBBLE_CONFIG.batReach&&offset.normalize().dot(direction)>.2){this.batHitIds.add(target.uuid);this.damageTarget(target,TOXIC_BUBBLE_CONFIG.batDamage);hit=true;}}const boss=this.endBoss;if(boss&&!boss.isDisposed&&boss.state!=='DEFEATED'){const offset=boss.root.getWorldPosition(new THREE.Vector3()).sub(origin),distance=offset.length();if(distance<=TOXIC_BUBBLE_CONFIG.batReach&&offset.normalize().dot(direction)>.2){boss.takeDamage(1);hit=true;}}this.setState(this.state,hit?'Bat hit! Close-range damage dealt.':'Swing! Move closer and face a target.');return true;}
