    fireFlame(origin,direction){if(!canActivateTool(this.state,rangeActive,Boolean(document.querySelector('dialog[open], #crib-chat-panel:not([hidden])'))))return false;if(rangeActive&&Number.isFinite(rangeCourses[rangeMode].shots)&&rangeShots>=rangeCourses[rangeMode].shots)return false;const fired=this.flameSystem.fire(origin,direction);if(!fired&&this.flameSystem.fuel===0){this.flameTrigger=null;this.setState(this.state,'Flash Igniter empty — collect a pink fuel refill.');}if(fired){this.gasSound(.025);if(rangeActive){rangeShots++;updateRangeReadout();}}this.updateHud();return fired;}
